// Hand-written `@trpc/server` stub for the flowatlas fixture suite.
//
// Shaped like the real package in the two ways the reading depends on, because a
// stub that got either wrong would make this fixture prove nothing (R63).
//
// First, nothing here is a class. `initTRPC` is a *value* whose `create` hands
// back the root object, and `router`, `procedure` and `middleware` are members of
// that object rather than constructors — which is exactly why a repository
// re-exports them under its own names, and why the reader matches the assembling
// function by name rather than by the type of its receiver.
//
// Second, a procedure builder's methods return *another builder*, so a chain is
// arbitrarily long and its last link is the only one that ends it. `input` and
// `use` therefore return `ProcedureBuilder`, and only `query`, `mutation` and
// `subscription` return a procedure. A stub where `input` returned a procedure
// would let the fixture pass with a reader that only ever looked one call deep.
//
// It declares less than the library: no context generics, no output validation,
// no error formatter, no type inference. It declares nothing of a different kind.

export interface Procedure {
  readonly _procedure: true;
}

export interface Router {
  readonly _router: true;
}

export type AnyRouter = Router;

export type Resolver = (opts: { ctx: unknown; input: unknown }) => unknown;

export type MiddlewareFunction = (opts: {
  ctx: unknown;
  next: (opts?: { ctx: unknown }) => unknown;
}) => unknown;

export interface Middleware {
  readonly _middleware: true;
}

export interface ProcedureBuilder {
  input(schema: unknown): ProcedureBuilder;
  output(schema: unknown): ProcedureBuilder;
  use(middleware: Middleware | MiddlewareFunction): ProcedureBuilder;
  query(resolver: Resolver): Procedure;
  mutation(resolver: Resolver): Procedure;
  subscription(resolver: Resolver): Procedure;
}

/** What a router is assembled out of: procedures, and routers, by name. */
export type RouterShape = Record<string, Procedure | Router>;

export interface TRPCRoot {
  router(shape: RouterShape): Router;
  mergeRouters(...routers: Router[]): Router;
  middleware(fn: MiddlewareFunction): Middleware;
  readonly procedure: ProcedureBuilder;
}

export interface TRPCInit {
  context<TContext>(): TRPCInit;
  create(options?: { transformer?: unknown }): TRPCRoot;
}

export declare const initTRPC: TRPCInit;
